<h1>Kiriman Fans</h1><nav class="cari"><?php foreach(REVIEW_STATUSES as $s): ?><a href="index.php?r=fan_submissions&amp;status=<?= e($s) ?>"><?= e(ucfirst($s)) ?></a><?php endforeach; ?></nav><?php foreach($items as $item): ?><article class="kartu"><strong><?= e($item['name']) ?></strong> · <?= e($item['email']) ?> · <?= e($item['type']) ?><?php if($item['city']): ?> · <?= e($item['city']) ?><?php endif; ?><p><?= nl2br(e($item['content'])) ?></p><?php if($item['file_url']): ?><img class="preview" src="<?= e(admin_asset($item['file_url'])) ?>" alt="Karya penggemar"><?php endif; ?><div class="aksi"><?php foreach(['approved'=>'Setujui','rejected'=>'Tolak','delete'=>'Hapus'] as $do=>$label): if($do!==$status): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="do" value="<?= e($do) ?>"><button class="<?= $do==='approved'?'btn':'hapus' ?>"><?= e($label) ?></button></form><?php endif; endforeach; ?></div></article><?php endforeach; ?><?php if(!$items): ?><p>Belum ada kiriman dalam kategori ini.</p><?php endif; ?>
